test('runs a single task and returns its value', async () => {
  const queue = new AsyncQueue();
  const result = await queue.add(() => Promise.resolve(42));
  expect(result).toBe(42);
});

test('tasks run sequentially, not concurrently', async () => {
  const queue = new AsyncQueue();
  const order = [];
  const delay = ms => new Promise(r => setTimeout(r, ms));
  queue.add(async () => { await delay(20); order.push(1); });
  queue.add(async () => { order.push(2); });
  await queue.add(async () => { order.push(3); });
  expect(order).toEqual([1, 2, 3]);
});

test('each add resolves with correct value', async () => {
  const queue = new AsyncQueue();
  const p1 = queue.add(() => Promise.resolve('a'));
  const p2 = queue.add(() => Promise.resolve('b'));
  expect(await p1).toBe('a');
  expect(await p2).toBe('b');
});

